ALTER TABLE public.produtos DROP CONSTRAINT IF EXISTS produtos_percentual_minimo_custo_venda_check; ALTER TABLE public.produtos ADD CONSTRAINT produtos_percentual_minimo_custo_venda_check CHECK (percentual_minimo_custo_venda >= 0 AND percentual_minimo_custo_venda <= 1000); COMMENT ON COLUMN public.produtos.percentual_minimo_custo_venda IS 'Percentual de acrescimo minimo sobre custo: 100 significa preco minimo = 2 vezes o custo';
